const envelope = $input.first().json || {};
const headers = envelope.headers || {};
const query = envelope.query || {};
let body = envelope.body && typeof envelope.body === 'object' ? envelope.body : envelope;

// Some senders submit a JSON string body. Parse it defensively.
if (typeof envelope.body === 'string') {
  try {
    body = JSON.parse(envelope.body);
  } catch (_e) {
    body = { message_text: envelope.body };
  }
}

const payload = body?.payload && typeof body.payload === 'object' ? body.payload : body;
const data = body?.data && typeof body.data === 'object' ? body.data : {};

function firstText(...values) {
  for (const v of values) {
    if (v === undefined || v === null) continue;
    if (typeof v === 'object') continue;
    const s = String(v).trim();
    if (s && s.toLowerCase() !== 'empty') return s;
  }
  return '';
}
function cleanId(v) {
  return String(v || '').trim().replace(/[^a-zA-Z0-9:_-]/g, '').slice(0, 180);
}
function cleanPhone(v) {
  return String(v || '').replace(/[^\d]/g, '').slice(0, 20);
}
function headerValue(name) {
  const expected = name.toLowerCase();
  for (const [k, v] of Object.entries(headers || {})) {
    if (String(k).toLowerCase() === expected) {
      return Array.isArray(v) ? String(v[0] || '') : String(v || '');
    }
  }
  return '';
}
function hash(s) {
  let h = 2166136261;
  s = String(s || '');
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0).toString(16);
}

const expectedSecret = String($env.N8N_INBOUND_SECRET || '').trim();
const receivedSecret = firstText(
  headerValue('x-n8n-inbound-secret'),
  headerValue('x-huygen-n8n-secret'),
  headerValue('x-inbound-secret'),
  payload.secret,
  payload.n8n_inbound_secret,
  body.secret,
  body.n8n_inbound_secret,
  query.secret,
  query.n8n_inbound_secret,
  query.inbound_secret
);

if (!expectedSecret) {
  throw new Error('N8N_INBOUND_SECRET is missing in the n8n environment.');
}
if (receivedSecret !== expectedSecret) {
  return [];
}

const rawEvent = firstText(payload.event_type, payload.type, data.event_type, body.event_type, body.type, 'whatsapp.inbound_message').toLowerCase();
if (rawEvent.includes('status') || rawEvent.includes('delivery') || rawEvent.includes('read')) {
  return [];
}

let actionId = cleanId(firstText(
  payload.interactive_reply_id,
  payload.action_id,
  payload.button_id,
  payload.selected_option_id,
  payload.interactive?.button_reply?.id,
  payload.interactive?.list_reply?.id,
  data.interactive_reply_id,
  data.action_id,
  body.interactive_reply_id,
  body.action_id
));
const actionTitle = firstText(
  payload.interactive_reply_title,
  payload.action_title,
  payload.button_title,
  payload.interactive?.button_reply?.title,
  payload.interactive?.list_reply?.title,
  data.interactive_reply_title,
  data.action_title,
  body.interactive_reply_title,
  body.action_title
);
const messageText = firstText(
  payload.message_text,
  payload.inbound_text,
  payload.text,
  typeof payload.message === 'string' ? payload.message : '',
  payload.message?.text,
  payload.customer_message,
  data.message_text,
  data.message,
  data.text,
  data.message?.text,
  body.message_text,
  body.message,
  body.text,
  body.message?.text,
  actionTitle,
  actionId
);

// Some CRM webhook templates preserve only the button title. Route those
// titles exactly like Meta's stable interactive reply ids.
if (!actionId) {
  const normalizedAction = messageText.toLowerCase().trim().replace(/[_-]+/g, ' ').replace(/\s+/g, ' ');
  actionId = ({
    'hi': 'show_menu',
    'hello': 'show_menu',
    'hey': 'show_menu',
    'good morning': 'show_menu',
    'good afternoon': 'show_menu',
    'good evening': 'show_menu',
    'namaste': 'show_menu',
    'find property': 'find_property',
    'book site visit': 'book_site_visit',
    'talk to agent': 'talk_to_agent',
    'buy': 'buy',
    'rent': 'rent',
    'sell/lease': 'sell_lease',
  })[normalizedAction] || '';
}

if (!messageText && !actionId && !payload.media_id && !body.media_id && !data.media_id) {
  throw new Error('No customer message found. In the CRM Send Webhook action, clear Body Template JSON so the CRM sends its default payload, and put the n8n secret in the webhook URL as ?secret=YOUR_N8N_INBOUND_SECRET. The custom {{message}}/{{phone}} variables are currently resolving to empty.');
}

const organizationId = cleanId(firstText(payload.organization_id, payload.organizationId, payload.org_id, data.organization_id, data.organizationId, data.org_id, body.organization_id, body.organizationId, body.org_id));
const conversationId = cleanId(firstText(payload.conversation_id, payload.conversationId, payload.conversationID, data.conversation_id, data.conversationId, data.conversationID, body.conversation_id, body.conversationId, body.conversationID));
const contactId = cleanId(firstText(payload.contact_id, payload.contactId, payload.customer_id, data.contact_id, data.contactId, data.customer_id, body.contact_id, body.contactId, body.customer_id));
const messageId = cleanId(firstText(payload.message_id, payload.messageId, payload.whatsapp_message_id, payload.wamid, data.message_id, data.messageId, data.whatsapp_message_id, data.wamid, body.message_id, body.messageId, body.whatsapp_message_id, body.wamid));
const phone = cleanPhone(firstText(payload.customer_phone, payload.customerPhone, payload.phone, payload.contact?.phone, data.customer_phone, data.customerPhone, data.phone, data.contact?.phone, body.customer_phone, body.customerPhone, body.phone, body.contact?.phone));
const customerName = firstText(payload.customer_name, payload.customerName, payload.contact_name, payload.contact?.name, payload.name, data.customer_name, data.customerName, data.contact_name, data.contact?.name, data.name, body.customer_name, body.customerName, body.contact_name, body.name);
const seed = [rawEvent, organizationId, conversationId, contactId, messageId, phone, messageText, payload.timestamp, data.timestamp, body.timestamp, Date.now()].join('|');
const eventId = cleanId(firstText(payload.event_id, payload.eventId, data.event_id, data.eventId, body.event_id, body.eventId, body.idempotency_key, messageId, `crm:${hash(seed)}`));

const event = {
  event_id: eventId,
  event_type: rawEvent === 'new_message_received' ? 'whatsapp.inbound_message' : rawEvent,
  organization_id: organizationId || null,
  conversation_id: conversationId || null,
  contact_id: contactId || null,
  message_id: messageId || null,
  message_text: messageText,
  interactive_reply_id: actionId || null,
  interactive_reply_title: actionTitle || null,
  message_type: firstText(payload.message_type, data.message_type, body.message_type, actionId ? 'interactive' : 'text'),
  media_id: cleanId(firstText(payload.media_id, data.media_id, body.media_id)) || null,
  customer_phone: phone,
  customer_name: customerName,
  received_at: firstText(payload.received_at, payload.timestamp, data.received_at, data.timestamp, body.received_at, body.timestamp, new Date().toISOString()),
  source: firstText(payload.source, data.source, body.source, 'huygen_crm')
};

return [{ json: { event, raw_payload: payload } }];

const input = $input.first().json || {};

function clean(v) { return String(v ?? '').trim(); }
function cleanUrl(v) { return clean(v).replace(/\/+$/, ''); }
function joinUrl(base, path) { return cleanUrl(base) ? `${cleanUrl(base)}${path}` : ''; }
function intRange(v, fallback, min, max) {
  const n = Number.parseInt(clean(v), 10);
  return Number.isFinite(n) ? Math.max(min, Math.min(max, n)) : fallback;
}
function hash(s) {
  let h = 2166136261;
  s = String(s || '');
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0).toString(16);
}
function firstText(...values) {
  for (const v of values) {
    if (v === undefined || v === null) continue;
    if (typeof v === 'object') continue;
    const s = String(v).trim();
    if (s) return s;
  }
  return '';
}
function cleanId(v) { return String(v || '').trim().replace(/[^a-zA-Z0-9:_-]/g, '').slice(0, 180); }
function cleanPhone(v) { return String(v || '').replace(/[^\d]/g, '').slice(0, 20); }

// Primary path: event from Normalize node.
let event = input.event;

// Fallback path: reconstruct event directly from webhook input if this node is run from copied execution data or n8n loses node state.
if (!event || typeof event !== 'object') {
  let webhook = {};
  try { webhook = $('Webhook - Real Estate AI Agent Real Estate Inbound').first().json || {}; } catch (_) { webhook = {}; }
  const body = webhook.body && typeof webhook.body === 'object' ? webhook.body : (input.body && typeof input.body === 'object' ? input.body : input);
  const payload = body?.payload && typeof body.payload === 'object' ? body.payload : body;
  const messageText = firstText(payload.message_text, payload.message, payload.text, body.message_text, body.message, body.text);
  const phone = cleanPhone(firstText(payload.customer_phone, payload.phone, body.customer_phone, body.phone));
  const messageId = cleanId(firstText(payload.message_id, payload.messageId, payload.whatsapp_message_id, body.message_id, body.messageId));
  const seed = [messageId, phone, messageText, payload.timestamp, body.timestamp].join('|');
  event = {
    event_id: cleanId(firstText(payload.event_id, payload.eventId, body.event_id, body.eventId, messageId, `crm:${hash(seed)}`)),
    event_type: firstText(payload.event_type, payload.type, body.event_type, body.type, 'whatsapp.inbound_message'),
    organization_id: cleanId(firstText(payload.organization_id, payload.organizationId, body.organization_id, body.organizationId)) || null,
    conversation_id: cleanId(firstText(payload.conversation_id, payload.conversationId, body.conversation_id, body.conversationId)) || null,
    contact_id: cleanId(firstText(payload.contact_id, payload.contactId, body.contact_id, body.contactId)) || null,
    message_id: messageId || null,
    message_text: messageText,
    message_type: firstText(payload.message_type, body.message_type, 'text'),
    media_id: cleanId(firstText(payload.media_id, body.media_id)) || null,
    customer_phone: phone,
    customer_name: firstText(payload.customer_name, payload.customerName, payload.name, body.customer_name, body.customerName, body.name),
    received_at: firstText(payload.received_at, payload.timestamp, body.received_at, body.timestamp, new Date().toISOString()),
    source: firstText(payload.source, body.source, 'huygen_crm')
  };
}

if (!event || typeof event !== 'object' || !event.event_id || !event.message_text) {
  throw new Error('Normalized event could not be built. Send body.secret plus message_text/message, and ideally event_id/message_id.');
}

const base = cleanUrl($env.HUYGEN_BASE_URL || $env.NEXT_PUBLIC_SITE_URL);
const config = {
  n8nInternalSecret: clean($env.N8N_INTERNAL_SECRET),
  contextUrl: cleanUrl($env.HUYGEN_N8N_CONTEXT_URL) || joinUrl(base, '/api/internal/n8n/real-estate/context'),
  propertyMatchUrl: cleanUrl($env.HUYGEN_PROPERTY_MATCH_URL) || joinUrl(base, '/api/internal/n8n/real-estate/property-match'),
  agentPlanUrl: cleanUrl($env.HUYGEN_AGENT_PLAN_URL) || joinUrl(base, '/api/internal/n8n/real-estate/agent-plan'),
  internalSendUrl: cleanUrl($env.HUYGEN_INTERNAL_SEND_URL) || joinUrl(base, '/api/internal/n8n/send-message'),
  eventStatusUrl: cleanUrl($env.HUYGEN_N8N_EVENT_STATUS_URL) || joinUrl(base, '/api/internal/n8n/real-estate/event-status'),
  openaiApiKey: clean($env.OPENAI_API_KEY),
  openaiModel: clean($env.OPENAI_MODEL) || 'gpt-4o-mini',
  defaultFollowupHours: intRange($env.REAL_ESTATE_DEFAULT_FOLLOWUP_HOURS, 24, 1, 168),
  hotFollowupHours: intRange($env.REAL_ESTATE_HOT_FOLLOWUP_HOURS, 4, 1, 72),
};

const missing = [];
if (!config.n8nInternalSecret) missing.push('N8N_INTERNAL_SECRET');
if (!config.openaiApiKey) missing.push('OPENAI_API_KEY');
if (!base && (!config.contextUrl || !config.propertyMatchUrl || !config.agentPlanUrl || !config.internalSendUrl || !config.eventStatusUrl)) {
  missing.push('HUYGEN_BASE_URL or explicit HUYGEN_N8N_* URLs');
}
if (missing.length) throw new Error(`Required environment variables are missing: ${missing.join(', ')}`);

return [{ json: { event, config, raw_payload: input.raw_payload || null } }];

const seed = $('CONFIG - Read Render Environment').first().json;
const response = $input.first().json || {};
const context = response.data || response.context || response;

if (!context || !context.organization || !context.organization.id) {
  throw new Error('Real Estate AI Agent context endpoint returned no organization context.');
}

// The Real Estate AI Agent backend is the source of truth for tenant/org resolution.
// Some CRM automation payloads do not expose organization_id, so Normalize may use a placeholder.
// Validate only when a real event org id was supplied. Otherwise adopt the backend-resolved org id.
const contextOrgId = String(context.organization.id || '').trim();
const eventOrgId = String(seed.event?.organization_id || '').trim();
const placeholderOrgIds = new Set(['', 'default-org', 'unknown', 'null', 'undefined']);

if (!placeholderOrgIds.has(eventOrgId.toLowerCase()) && eventOrgId !== contextOrgId) {
  throw new Error(`Organization mismatch in secure context response. event=${eventOrgId} context=${contextOrgId}`);
}

const normalizedEvent = {
  ...seed.event,
  organization_id: contextOrgId,
  conversation_id: context.conversation?.id || seed.event.conversation_id,
  contact_id: context.contact?.id || seed.event.contact_id,
  customer_phone: context.contact?.phone || seed.event.customer_phone,
  customer_name: context.contact?.name || seed.event.customer_name,
};

return [{
  json: {
    event: normalizedEvent,
    config: seed.config,
    context,
  }
}];

const item = $input.first().json;
const text = String(item.event?.message_text || '').trim().toLowerCase();
const isOptOutRequest = /^(stop|unsubscribe|opt out|optout|cancel)$/i.test(text);
const duplicate = item.context?.event_is_duplicate === true || item.context?.event_already_completed === true;
const paused = item.context?.conversation?.automation_paused === true;

// Agent mode must keep the automation running even if a stale handoff flag is true.
// Only block when the conversation is actually owned by a human/manual mode.
const automationMode = String(item.context?.conversation?.automation_mode || '').trim().toLowerCase();
const handoffActive = item.context?.conversation?.handoff_active === true;
const humanOwnedModes = new Set(['human', 'manual', 'paused', 'off', 'disabled']);
const activeHumanHandoff = handoffActive && (humanOwnedModes.has(automationMode) || !automationMode);

return [{
  json: {
    ...item,
    is_opt_out_request: isOptOutRequest,
    preflight: {
      duplicate,
      paused,
      handoff_active: handoffActive,
      automation_mode: automationMode || null,
      active_human_handoff_blocks_automation: activeHumanHandoff,
    },
    skip_processing: Boolean(duplicate || (paused && !isOptOutRequest) || (activeHumanHandoff && !isOptOutRequest)),
  }
}];

