function clean(v,m=180){return String(v??'').trim().slice(0,m);} function en(v,a,f='unknown'){v=clean(v,60).toLowerCase();return a.includes(v)?v:f;} function pi(v,max=100){const n=parseInt(v,10);return Number.isFinite(n)&&n>0?Math.min(n,max):null;} function pm(v){if(v==null||v==='')return null;const n=Number(String(v).replace(/[^\d.]/g,''));return Number.isFinite(n)&&n>=0?Math.round(n):null;} function pn(v){if(v==null||v==='')return null;const n=Number(String(v).replace(/[^\d.]/g,''));return Number.isFinite(n)&&n>0?n:null;} function arr(v,n=8,m=80){return Array.isArray(v)?v.map(x=>clean(x,m)).filter(Boolean).slice(0,n):[];} function keep(a,b,f=null){return a!==null&&a!==undefined&&a!==''?a:(b!==null&&b!==undefined&&b!==''?b:f);}
