nities.length?amenities:(Array.isArray(e.amenities)?e.amenities:[]),site_visit_interest:en(keep(s.site_visit_interest,e.site_visit_interest),['yes','no','unknown']),preferred_appointment_date:clean(s.preferred_appointment_date||'',80),preferred_appointment_time:clean(s.preferred_appointment_time||'',80),preferred_appointment_at:clean(s.preferred_appointment_at||'',120),property_reference:clean(s.property_reference||'',120),seller_property_details:clean(s.seller_property_details||e.seller_property_details||'',500)};
