const missing=[]; if(!hasIntent)missing.push('buy/rent/sell intent'); if(!hasLocation&&!isSeller)missing.push('preferred location'); if(!hasBudget)missing.push(isSeller?'expected price/rent':'budget range'); if(!hasCategory&&!hasType)missing.push('property category/type'); if(isLand&&!hasArea)missing.push('plot area'); if(!isLand&&!hasBeds&&!hasArea&&!isSeller)missing.push('bedrooms or area'); if(!hasTimeline)missing.push('timeline'); if(isLand&&!r.approval_authority)missing.push('plot approval/title details');
