function formatPrice(match) {
  if (match.price === null || match.price === undefined || match.price === '') return '';
  const value = Number(match.price);
  if (!Number.isFinite(value)) return '';
  return `${match.currency || 'INR'} ${value.toLocaleString('en-IN')}`;
}

