  if (!matches.length) {
    return `I could not find an exact currently available match yet. Which requirement can be flexible: locality, budget, or property type?`;
  }
  const lines = matches.map((m, index) => {
    const parts = [m.title, m.locality || m.city, m.bedrooms ? `${m.bedrooms} BHK` : '', formatPrice(m)].filter(Boolean);
    return `${index + 1}. ${parts.join(' — ')}`;
  });
  return `I found ${matches.length} currently available option${matches.length > 1 ? 's' : ''} that may fit your requirement:\n${lines.join('\n')}\n\nReply with a property number or ask to book a site visit.`;
}

